INSERT INTO tb_outbox_event (
    event_type, aggregate_id, payload, status, topic, message_key,
    retry_count, max_retry, failure_reason, created_time, published_time
)
VALUES (
    #{eventType}, #{aggregateId}, #{payload}, #{status}, #{topic}, #{messageKey},
    IFNULL(#{retryCount}, 0), IFNULL(#{maxRetry}, 3), #{failureReason}, #{createdTime}, #{publishedTime}
)
